function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',5000);}
async function load(){if(!hasSession())return;try{state=await api('state');offline=false;if(!routed){routed=true;routeFromHash(false);}render();}catch(e){if(e.name==='AbortError')return;if(e.status===401){setSession('');return;}if(!e.status&&listPackets().length){offline=true;root.innerHTML=offlinePage();bindOffline();return;}root.innerHTML=`<div class="empty"><h2>Workspace unavailable</h2><p>${esc(e.message)}</p><button id="retry-open">Retry</button></div>`;$('#retry-open').onclick=load;}}
let routed=false;
// Stable deep links: #/station/ID, #/incident/ID, #/plan/ID, #/packet/ID and #/<view>.
function hashFor(){return view==='station'?'#/station/'+encodeURIComponent(selected):view==='incident'?'#/incident/'+selectedIncident:view==='plan'?'#/plan/'+selectedPlan:view==='packet'?'#/packet/'+selectedPacket:'#/'+view;}
function pushHash(){const h=hashFor();if(location.hash!==h)window.history.pushState(null,'',h);}
function routeFromHash(draw=true){const h=decodeURIComponent(location.hash);let m;if(!h.startsWith('#/'))return;if(m=h.match(/^#\/station\/([A-Za-z0-9_-]{1,100})$/)){if(selected!==m[1]||view!=='station')openStation(m[1],{push:false,draw});return;}if(m=h.match(/^#\/incident\/([a-f0-9-]{36})$/)){selectedIncident=m[1];view='incident';}else if(m=h.match(/^#\/plan\/([a-f0-9-]{36})$/)){selectedPlan=m[1];view='plan';}else if(m=h.match(/^#\/packet\/([a-f0-9-]{36})$/)){selectedPacket=m[1];view='packet';}else if(m=h.match(/^#\/([a-z]+)$/))view=m[1];else return;if(draw)render();}
window.addEventListener('popstate',()=>{if(hasSession()&&!offline)routeFromHash();});
function offlinePage(){const list=listPackets();return `<div class="workspace"><div class="alert"><strong>Offline.</strong> The workspace cannot reach the server. Saved field packets on this device are below; they are read-only and not current.</div><section class="panel"><div class="panelhead"><h2>Saved field packets</h2></div>${list.map(p=>`<div class="queueitem"><div class="grow"><div class="name">${esc(p.title)}</div><p>${esc(p.date)} · saved ${date(p.savedAt)} ET by ${esc(p.savedBy)}</p></div><button class="small" data-offline-packet="${esc(p.id)}">View</button></div>`).join('')}</section><p><a href="/field-notes/">Open the offline field notebook</a> · <button class="small" id="retry-open">Retry connection</button></p></div>`;}
function bindOffline(){$('#retry-open').onclick=load;root.querySelectorAll('[data-offline-packet]').forEach(b=>b.onclick=()=>{selectedPacket=b.dataset.offlinePacket;root.innerHTML=`<div class="workspace"><button class="back" id="offline-back">← Packets</button>${packetPage({heading,state},selectedPacket)}</div>`;$('#offline-back').onclick=()=>{root.innerHTML=offlinePage();bindOffline();};const pr=$('#print-packet');if(pr)pr.onclick=()=>window.print();});}
function clearPrivateState(){
 state={stations:[],records:[],connection:{}};view='overview';selected=null;selectedIncident=null;selectedPlan=null;selectedPacket=null;routed=false;resetOps();resetPlanner();resetFleetSettings();clearPackets();if(location.hash.startsWith('#/'))window.history.replaceState(null,'',location.pathname);history=null;historyError='';historyLoading=false;historyTicket++;comparison=null;comparisonBusy=false;comparisonTicket++;productCache=null;sharedVisits=[];teamUsers=[];analysis=null;analysisName='';analysisVariable='';busy=false;search='';clearReports();clearInterval(radarTimer);if(map){map.remove();map=null;}
 for(const dialog of document.querySelectorAll('dialog')){if(dialog.open)dialog.close();dialog.replaceChildren();}
 $('#toast').textContent='';$('#toast').style.display='none';showAuth(root,()=>load());
}
window.addEventListener('fleet-session-changed',()=>{if(!hasSession())clearPrivateState();});
function setView(next){comparisonTicket++;comparisonBusy=false;view=next;historyTicket++;historyLoading=false;pushHash();render();}
function openIncident(id){selectedIncident=id;refreshIncident();view='incident';pushHash();render();}
function openPlan(id){selectedPlan=id;view='plan';pushHash();render();}
function openPacket(id){selectedPacket=id;view='packet';pushHash();render();}
function openPlanner(opts){openPlannerWith(opts);setView('planner');}
function heading(kicker,title,sub,actions=''){return `<div class="heading"><div><h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function render(){if(!hasSession())return;const moduleCtx={state,api,toast,rerender:render};configureOps(moduleCtx);configurePlanner(moduleCtx);clearInterval(radarTimer);if(map){const previousMap=map;map=null;previousMap.remove();}const navGroups=[['Workspace',[['overview','grid','Overview'],['review','activity','Daily review'],['stations','pin','Stations'],['planner','route','Field-day planner'],['plans','list','Saved plans'],['alerts','bell',`Alerts${state.ops?.openAlerts?` (${state.ops.openAlerts})`:''}`]]],['Analysis',[['anomalies','alert','Anomaly report'],['tracker','activity','Reference tracker'],['bench','tool','Bench testing']]],['Records',[['issues','list','Investigations'],['visits','list','Field Notes']]],['Account',[['connections','link','Connections'],['account','link','My account'],...(state.user?.role==='owner'?[['team','link','Team access']]:[])]]];
const parentOf={station:'stations',incident:'review',plan:'plans',packet:'plans'},isActive=id=>view===id||parentOf[view]===id;const navButton=([id,ic,label])=>`<button data-nav="${id}" class="${isActive(id)?'active':''}" ${isActive(id)?'aria-current="page"':''}>${icon(ic)}${label}</button>`;
root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${icon('leaf')}<div>Enviroweather<small>Fleet operations</small></div></div><nav class="nav" aria-label="Main navigation">${navGroups.map(([group,items])=>`<div class="navgroup"><div class="navlabel">${group}</div>${items.map(navButton).join('')}</div>`).join('')}</nav><div class="sidefoot"><div><span class="avatar">${esc((state.user?.name||'EW').slice(0,2).toUpperCase())}</span>${esc(state.user?.name||'Team workspace')}</div><p class="versions">Web ${esc(FRONTEND_RELEASE)} · API ${esc(state.release?.version||'unknown')}${state.release?.release?' ('+esc(state.release.release)+')':''}</p></div></aside><main class="main"><header class="topbar"><div class="crumb"><span class="dot ${state.fetchedAt?'':'off'}"></span><span>${state.fetchedAt?'Snapshot '+date(state.fetchedAt)+' ET':'No network snapshot yet'}</span></div><div class="topstatus"><span>${esc(state.user?.email||'Team workspace')}</span><button class="small" id="signout">Sign out</button></div></header><div class="workspace">${state.release?.protocol!==FRONTEND_PROTOCOL?`<div class="alert error" role="alert">This page expects API protocol ${FRONTEND_PROTOCOL}; the API reports ${esc(state.release?.protocol||'an older version')}. Operations views are unavailable until matching frontend and API versions are deployed. Existing records remain safe.</div>`:''}${state.lastError&&!['overview','review'].includes(view)?`<div class="alert error">Refresh failed: ${esc(state.lastError)}. Showing saved data.</div>`:''}${state.cacheAgeMinutes>45&&!['overview','review'].includes(view)?`<div class="alert">Data fetched ${ago(state.cacheAgeMinutes)}. Refresh for an update.</div>`:''}<div id="page">${({overview:overview,review:()=>opsReview({state,heading,busy,icon}),incident:()=>incidentPage({heading,selectedIncident,state}),alerts:()=>alertsPage({heading}),planner:()=>plannerPage({state,heading}),plans:()=>plansPage({heading}),plan:()=>planPage({state,heading,selectedPlan}),packet:()=>packetPage({heading,state},selectedPacket),anomalies:anomalyPage,tracker:()=>trackerPage(state),stations:stations,station:stationPage,bench:bench,issues:issues,connections:connections,team:teamPage,visits:visitsPage,account:accountPage}[view]||overview)()}</div></div></main></div>`;bind();if((view==='overview'||view==='station'&&comparison)&&state.stations.length)drawMap();if(view==='station'&&!history&&!historyLoading&&!historyError)fetchHistory();}
function metric(label,value,hint,ic='activity',klass=''){const text=typeof value==='string'&&value.length>8&&!/^[\d.,\s\/%—-]+$/.test(value);return `<div class="metric ${klass}"><span class="label">${label}</span><div class="value${text?' text':''}">${value}</div>${hint?`<div class="hint">${hint}</div>`:''}</div>`;}
function help(title,text){return `<details class="note"><summary>${title}</summary><p class="footnote">${text}</p></details>`;}
function compactReason(s){const reason=({clock:'Station clock is ahead',unknown:'No timestamped readings',stale:'Last reading '+ago(s.ageMinutes),delayed:'Last reading '+ago(s.ageMinutes),qc:'QC flag on latest reading',inactive:'Inactive station',reporting:'Recent reading'})[s.status]||labels[s.status];return reason+(s.flagged&&s.status!=='qc'?' · QC flagged':'');}
function empty(title,text,action=''){return `<div class="empty">${icon('activity')}<h2>${title}</h2>${text?`<p>${text}</p>`:''}${action}</div>`;}
function overview(){const ops=state.ops,a=active(),changed=ops?.recentAlerts||[];return heading('Workspace','Overview','',`<a class="linkbutton" href="/api/ops/export">${icon('download')} Operations export</a><a class="linkbutton" href="/api/export">${icon('download')} Records export</a><button class="primary" data-refresh ${busy?'disabled':''}>${icon('refresh')} ${busy?'Refreshing…':'Refresh network'}</button>`)+`<p class="statusline">Network fetched <strong>${date(state.fetchedAt)} ET</strong>${state.cacheAgeMinutes!==null&&state.cacheAgeMinutes!==undefined?` (${ago(state.cacheAgeMinutes)})`:''} · ${a.length} active stations · polled every 15 minutes · upstream provider: Synoptic Data</p>`+(ops?feedBanner(ops,state)+countRow(ops):'')+(!state.connection.configured?`<div class="info">Connect Synoptic to load stations. <button class="small" data-nav="connections">Connect a data source</button></div>`:'')+(ops?`<section class="panel"><div class="panelhead"><div><h2>What comes first</h2><p>Canonical priority · ${ops.queue.length} open item${ops.queue.length===1?'':'s'} · select a row to locate it on the map</p></div><button class="small quiet" data-nav="review">Full Daily review</button></div>${queueFilters(ops)}${queueTable(ops,{limit:10})}</section>`:'')+`<div class="two-col"><section class="panel"><div class="panelhead"><div><h2>Michigan radar & network</h2><p>${esc(state.connection.networkName||'Enviroweather')} · marker colour shows each station's highest open tier</p></div></div><div class="radar-controls"><label><input id="radar-toggle" type="checkbox" ${radarEnabled?'checked':''}> Show radar</label><label>Opacity <input id="radar-opacity" type="range" min="10" max="100" value="${Math.round(radarOpacity*100)}"></label><button id="radar-refresh" class="small">Refresh radar</button></div>${state.stations.length?'<div id="map" class="map" aria-label="Map of station status by priority tier"></div>':empty('Your network belongs here','Live station coordinates appear after the first successful sync.')}<div class="radar-caption"><span id="radar-status" role="status">Loading radar…</span>${help('Radar details','Updates every 5 minutes. The displayed time is the image load time. Blank areas can mean missing coverage. Radar echoes are not measured rainfall.')}<a href="https://mesonet.agron.iastate.edu/ogc/" target="_blank" rel="noreferrer">NWS NEXRAD via Iowa Environmental Mesonet</a></div>${opsLegend()}</section><div><section class="panel"><div class="panelhead"><div><h2>What changed (24 h)</h2><p>${ops?.openAlerts||0} unacknowledged alert${ops?.openAlerts===1?'':'s'}</p></div><button class="small quiet" data-nav="alerts">Alerts</button></div>${changed.length?changed.map(x=>`<div class="queueitem"><div class="grow"><div class="name">${x.tier&&x.tier!=='FEED'?tierPill(x.tier):''} ${esc(x.title.replace(/^(?:P[1-4]|QC|PM) · /,''))}</div><p>${date(x.created)} ET · ${esc(x.kind)}${x.acknowledgedAt?' · acknowledged':''}</p></div>${x.incidentId?`<button class="small" data-incident="${esc(x.incidentId)}" aria-label="Open incident">${icon('arrow')}</button>`:''}</div>`).join(''):empty('No changes in the last 24 hours','')}</section><section class="panel"><div class="panelhead"><div><h2>Open cases</h2></div><button class="small" data-new="issue">+ Add field note</button></div>${openIssues().length?openIssues().slice(0,4).map(noteRow).join(''):empty('No open field notes','')}</section></div></div>${help('Detection and freshness',esc(ops?.detection?.note||'')+` Station reading status: delayed after ${state.connection.delayed||60} minutes; stale after ${state.connection.stale||180} minutes. Individual channels are judged against each station's expected-sensor profile.`)}`;}
function stationRows(list){const cell=f=>f?`<strong class="num">${num(f.value)} <span class="unit">${unitLabel(f.unit)}</span></strong><small>${date(f.time)} ET</small>`:'—';return list.map(s=>{const t=field(s,'air_temp'),w=field(s,'wind_speed');return `<tr class="station-row"><td><button class="station-link" data-station="${esc(s.id)}">${esc(s.name)}</button><small class="mono">${esc(s.id)}${s.state?' · '+esc(s.state):''}</small></td><td>${pill(s.status)}${s.flagged&&s.status!=='qc'?'<span class="qc-note">QC flags present</span>':''}</td><td>${ago(s.ageMinutes)}<small>${date(s.last)}${s.last?' ET':''}</small></td><td>${cell(t)}</td><td>${cell(w)}</td><td><button class="small quiet" data-station="${esc(s.id)}">Inspect</button></td></tr>`;}).join('');}
function filtered(){return state.stations.filter(s=>(!search||`${s.name} ${s.id}`.toLowerCase().includes(search.toLowerCase()))&&(filter==='all'||filter==='active'&&s.archiveStatus!=='INACTIVE'||filter==='attention'&&attention(s)||s.status===filter)).sort((a,b)=>a.name.localeCompare(b.name));}
function stations(){return heading('Workspace','Stations','',`<button class="primary" data-refresh ${busy?'disabled':''}>${icon('refresh')} Refresh</button>`)+`<section class="panel"><div class="filters"><label class="sr-only" for="search">Search stations</label><input id="search" placeholder="Search station name or ID…" value="${esc(search)}"><label class="sr-only" for="filter">Status</label><select id="filter">${[['active','Active inventory'],['all','All stations'],['attention','Needs attention'],['reporting','Reporting'],['delayed','Delayed'],['stale','Stale'],['qc','QC flagged'],['inactive','Inactive archive']].map(([v,t])=>`<option value="${v}" ${v===filter?'selected':''}>${t}</option>`).join('')}</select><span id="resultcount" class="text-muted">${filtered().length} stations</span></div><div class="tablewrap"><table><thead><tr><th>Station</th><th>Triage status</th><th>Newest measurement</th><th>Air temperature</th><th>Wind speed</th><th></th></tr></thead><tbody id="stationrows">${stationRows(filtered())}</tbody></table><div id="noresults" class="empty" ${filtered().length?'hidden':''}>No stations match this view.</div></div></section>${help('Reading status','Reporting means recent data without a QC flag. Inactive stations are archived. All displayed times are Eastern.')}`;}
function chart(times,values,qc=[],unit=''){const numeric=values.map((v,i)=>({v,t:times[i],i})).filter(p=>typeof p.v==='number'&&Number.isFinite(p.v));if(!numeric.length)return empty('No numeric observations','Try another sensor or time range.');const W=760,H=240,pad=45,lo=Math.min(...numeric.map(p=>p.v)),hi=Math.max(...numeric.map(p=>p.v)),span=hi-lo||1,min=lo-span*.12,max=hi+span*.12;const y=v=>H-pad-(v-min)/(max-min)*(H-2*pad);const parsed=times.map(t=>Date.parse(t)),finite=parsed.filter(Number.isFinite),first=finite.length?Math.min(...finite):0,last=finite.length?Math.max(...finite):times.length-1;const x=i=>pad+((finite.length===times.length?parsed[i]-first:i)/(finite.length===times.length?(last-first||1):Math.max(1,values.length-1)))*(W-2*pad);let path='',prev=false;values.forEach((v,i)=>{if(typeof v==='number'&&Number.isFinite(v)){path+=(prev?' L':' M')+x(i).toFixed(1)+' '+y(v).toFixed(1);prev=true;}else prev=false;});const flagged=i=>Array.isArray(qc?.[i])?qc[i].length>0:!!qc?.[i];return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(unit)} observations over the selected period"><text x="${pad}" y="16">${esc(unit)}</text>${[0,.5,1].map(r=>{const v=min+r*(max-min);return `<line class="grid" x1="${pad}" x2="${W-10}" y1="${y(v)}" y2="${y(v)}"/><text x="${pad-8}" y="${y(v)+3}" text-anchor="end">${num(v)}</text>`;}).join('')}<path class="line" d="${path}"/>${numeric.filter(p=>flagged(p.i)).map(p=>`<circle class="point" cx="${x(p.i)}" cy="${y(p.v)}" r="3"><title>${esc(p.t)} · ${num(p.v)} · QC ${esc(JSON.stringify(qc[p.i]))}</title></circle>`).join('')}<text x="${pad}" y="${H-10}">${esc(times[0]||'')}</text><text x="${W-10}" y="${H-10}" text-anchor="end">${esc(times.at(-1)||'')}</text></svg>`;}
function stationPage(){const s=state.stations.find(s=>s.id===selected);if(!s)return empty('Station unavailable','Refresh the network inventory.');const hs=history?.STATION?.[0],obs=hs?.OBSERVATIONS||{},variables=Object.keys(obs).filter(k=>k!=='date_time'&&Array.isArray(obs[k])&&!k.endsWith('_qc'));if(!variables.includes(historyVariable))historyVariable=variables.find(k=>k.startsWith('air_temp'))||variables[0]||'';const variable=historyVariable.replace(/_set_\d+.*/,'');return `<button class="back" data-nav="stations">← All stations</button>`+heading('Station · '+esc(s.id),esc(s.name),`${pill(s.status)} <span style="margin-left:6px">Latest measurement ${ago(s.ageMinutes)}</span>`,`<button data-new="issue" data-prefill="${esc(s.id)}">+ Field note</button>${state.user?.role!=='viewer'?`<button data-plan-stations="${esc(s.id)}">Plan visit</button>`:''}<button class="primary" data-investigate="${esc(s.id)}">${investigationFor(s.id)?'Open investigation':'Start investigation'}</button>`)+`${s.carriedForward?`<div class="alert">Missing from the latest provider response; values below were carried forward from ${date(s.carriedForward)} ET.</div>`:''}${stationOps(s.id,{canEdit:state.user?.role!=='viewer'})}${comparisonPanel(s)}<div class="obsgrid">${s.fields.filter(f=>!f.derived).sort((a,b)=>(b.variable==='volt')-(a.variable==='volt')).slice(0,9).map(f=>`<article class="obs"><h3>${esc(name(f.variable))}</h3><div class="reading">${reading(f.value)} <small>${unitLabel(f.unit)}</small></div><div class="when">${date(f.time)} ET · ${esc(f.key)}</div>${f.qc?.length?`<span class="qc-note">QC: ${esc(qcName(f.qc))}</span>`:''}${f.time&&Date.now()-Date.parse(f.time)>state.connection.delayed*60000?'<span class="qc-note">Delayed reading</span>':''}</article>`).join('')||'<div class="info">No latest numeric readings were returned.</div>'}</div><section class="panel"><div class="panelhead"><div><h2>Extended diagnostics</h2><p>Synoptic products for the selected history window</p></div></div><div class="panelbody"><div class="actions"><button data-product="precip" ${historyLoading?'disabled':''}>Rainfall totals</button><button data-product="localstats" ${historyLoading?'disabled':''}>Window statistics</button><button data-product="qcsegments" ${historyLoading?'disabled':''}>QC history</button></div><div id="product-results">${productCache?.station===s.id&&productCache.hours===historyHours?productCache.html:''}</div></div></section><div class="detailgrid"><div><section class="panel"><div class="panelhead"><div><h2>Observation history</h2><p>Orange dots: QC flags</p></div><select id="history-hours" aria-label="History window">${[[24,'24 hours'],[72,'3 days'],[168,'7 days']].map(([v,t])=>`<option value="${v}" ${v===historyHours?'selected':''}>${t}</option>`).join('')}</select></div><div class="panelbody">${historyLoading?'<div class="empty">Loading observations from Synoptic…</div>':historyError?`<div class="alert error">${esc(historyError)}</div><button data-retry-history>Retry history</button>`:variables.length?`<label class="sr-only" for="history-variable">Sensor</label><select id="history-variable">${variables.map(k=>`<option ${k===historyVariable?'selected':''} value="${esc(k)}">${esc(name(k))}</option>`).join('')}</select>${chart(obs.date_time||[],obs[historyVariable]||[],hs.QC?.[historyVariable]||[],UNIT_LABELS[history.UNITS?.[variable]]||history.UNITS?.[variable]||'')}<div class="actions"><button class="small" id="download-history">Download this history</button></div><p class="footnote">${obs.date_time?.length||0} readings · source: UTC · fetched ${date(history.fetchedAt)} ET</p>`:empty('No history returned','There may be no observations in this time window.')}</div></section><section class="panel"><div class="panelhead"><h2>All latest sensor values</h2></div><div class="tablewrap"><table><thead><tr><th>Sensor</th><th>Value</th><th>Observed ET / QC</th></tr></thead><tbody>${s.fields.map(f=>`<tr><td>${esc(f.key)}${f.derived?'<small>Derived variable</small>':''}</td><td><strong class="num">${reading(f.value)} <span class="unit">${unitLabel(f.unit)}</span></strong></td><td>${date(f.time)}<small>${f.qc?.length?esc(qcName(f.qc)):f.qcStatus==='passed'?'QC passed':'No flag returned'}</small></td></tr>`).join('')}</tbody></table></div></section></div><div><section class="panel"><div class="panelhead"><h2>Station context</h2></div><div class="panelbody"><dl class="definition"><dt>Synoptic ID</dt><dd class="mono">${esc(s.id)}</dd><dt>Network</dt><dd>${esc(s.network)}</dd><dt>Coordinates</dt><dd>${esc(s.lat)}, ${esc(s.lon)}</dd><dt>Archive status</dt><dd>${esc(s.archiveStatus)}</dd><dt>Logger model</dt><dd>Not connected</dd><dt>Voltage telemetry</dt><dd>${field(s,'volt')?num(field(s,'volt').value)+' V via Synoptic':'Not available'}</dd><dt>Modem / PakBus</dt><dd>Not connected</dd></dl></div></section><section class="panel"><div class="panelhead"><h2>Related field notes</h2></div>${state.records.filter(r=>r.kind==='issue'&&(r.station===s.id||s.name.toLowerCase().includes(r.station.toLowerCase())&&r.station)).map(noteRow).join('')||empty('Nothing recorded yet','Add a note to preserve your investigation.')}</section></div></div>`;}
async function fetchHistory(){const ticket=++historyTicket,id=selected;historyLoading=true;render();try{const h=await api('history?station='+encodeURIComponent(id)+'&hours='+historyHours);if(ticket!==historyTicket||selected!==id)return;history=h;historyError='';}catch(e){if(ticket!==historyTicket)return;historyError=e.message;}finally{if(ticket===historyTicket){historyLoading=false;if(view==='station')render();}}}
function noteRow(r){return `<div class="queueitem"><div class="queueicon">${icon(r.kind==='bench'?'tool':'list')}</div><div class="grow"><div class="name">${esc(r.title)} ${pill(r.status)}</div><p>${esc(r.station||'Unassigned')} · ${esc(r.source)}</p><p>${esc(r.notes||r.observed||'')}</p>${r.kind==='bench'?`<p>Result: ${esc(r.outcome)} · ${esc(r.equipment||'Equipment not recorded')}</p>`:''}</div><button class="small" data-record="${r.id}">Open</button></div>`;}
function issues(){const all=state.records.filter(r=>r.kind==='issue'),shown=all.filter(r=>caseFilter==='all'||r.status===caseFilter);return heading('Records','Investigations','',`<button class="primary" data-new="issue">+ Add field note</button>`)+`<section class="panel"><div class="panelhead"><div><h2>Cases</h2><p>${openIssues().length} open · ${all.filter(r=>r.status==='resolved').length} resolved</p></div></div><div class="filters">${[['open','Open'],['resolved','Resolved'],['all','All cases']].map(([v,l])=>`<button class="small ${caseFilter===v?'primary':''}" data-case-filter="${v}">${l}</button>`).join('')}</div>${shown.map(noteRow).join('')||empty('No cases in this view','Open a station to capture evidence or add a field note.')}</section>`;}

function bench(){const tests=state.records.filter(r=>r.kind==='bench');return heading('Analysis','Bench testing','',`<button class="primary" data-new="bench">+ New test record</button>`)+`<div class="two-col"><section class="panel"><div class="panelhead"><div><h2>Logger file inspector</h2><p>TOA5 / CSV · up to 8 MB</p></div></div><div class="panelbody"><div class="filezone">${icon('download')}<h3>Analyze a logger export</h3><p>Missing values, gaps and timestamp checks.</p><label class="sr-only" for="csv-file">Choose logger export</label><input id="csv-file" type="file" accept=".csv,.dat,.txt"><p><a href="/sample-logger.dat" download>Download sample file</a></p></div>${analysis?analysisView():`<p class="footnote">Import a file to view readings and statistics.</p>`}</div></section><section class="panel"><div class="panelhead"><div><h2>Test journal</h2><p>${tests.length} record${tests.length===1?'':'s'}</p></div></div>${tests.length?tests.map(noteRow).join(''):empty('No test records','')}</section></div>`;}
function analysisView(){return `<h3>${esc(analysisName)}</h3><p class="subtitle">${analysis.format} · ${analysis.rows} rows · ${analysis.columns} columns</p><div class="metrics" style="grid-template-columns:1fr 1fr;margin-top:12px">${metric('Timestamp reversals',analysis.reverseTimes,'Out-of-order recorded timestamps')}${metric('Sampling gaps',analysis.gaps,`Above 1.5× median interval (${analysis.medianIntervalSeconds??'—'} sec)`)}</div>${analysis.logger?`<div class="info">${esc(analysis.logger.model)} · Serial ${esc(analysis.logger.serial)} · ${esc(analysis.logger.program)}</div>`:''}<p class="footnote">${esc(analysis.start)} → ${esc(analysis.end)}<br>${esc(analysis.timeNote)}<br>${analysis.duplicateTimes} duplicate timestamps · ${analysis.recordResets} record counter decreases · ${analysis.malformedRows} malformed rows</p>${analysisChart()}<div class="tablewrap"><table><thead><tr><th>Column</th><th>Min / max</th><th>Missing</th><th>Note</th></tr></thead><tbody>${analysis.stats.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.unit)}</small></td><td class="num">${num(s.min)} / ${num(s.max)}</td><td class="num">${s.missing}</td><td>${s.constant?'Constant; inspect context':'—'}</td></tr>`).join('')}</tbody></table></div><div class="actions" style="margin-top:14px"><button class="small" id="download-analysis">Download analysis JSON</button><button class="small" data-new="bench">Record a test</button></div>`;}
function analysisChart(){const columns=analysis.stats.filter(s=>s.count>0&&s.name!=='RECORD');if(!columns.length)return '';if(!columns.some(s=>s.name===analysisVariable))analysisVariable=columns[0].name;const col=columns.find(s=>s.name===analysisVariable),times=analysis.sample.map((r,i)=>analysis.timeColumn?r[analysis.timeColumn]:String(i)),values=analysis.sample.map(r=>{const raw=r[analysisVariable]?.trim();return raw!==''&&Number.isFinite(Number(raw))?Number(raw):null;});return `<div style="margin-top:16px"><label for="file-variable" class="sr-only">File sensor column</label><select id="file-variable">${columns.map(s=>`<option value="${esc(s.name)}" ${s.name===analysisVariable?'selected':''}>${esc(s.name)}</option>`).join('')}</select>${chart(times,values,[],col.unit)}<p class="footnote">Preview of up to 500 evenly sampled rows; statistics above use every row. Source timestamps are unchanged.</p></div>`;}
function connections(){return heading('Account','Connections','')+`<section class="panel"><div class="panelhead"><div><h2>Weather data</h2><p>Synoptic Weather API · network ${esc(state.connection.network)}</p></div><span class="pill ${state.connection.configured?'reporting':'unknown'}">${state.connection.configured?'Configured':'Setup needed'}</span></div><div class="panelbody"><p>Stations, readings, history, QC and precipitation. Refreshes every 15 minutes.</p><p>Last successful refresh: <strong>${date(state.fetchedAt)} ET</strong></p><button class="primary" data-refresh ${busy?'disabled':''}>Refresh and verify connection</button><p class="footnote"><a href="https://docs.synopticdata.com/services" target="_blank" rel="noreferrer">Synoptic API documentation</a></p><h3>Michigan radar</h3><p>NWS radar imagery through Iowa Environmental Mesonet. No account is required.</p></div></section>${fleetSettingsPanel()}<section class="panel"><div class="panelhead"><h2>Work accounts</h2></div><div class="panelbody"><h3>Teams · Field Notes</h3><p>PDF sharing · automatic uploads not connected</p><a class="linkbutton" href="https://teams.cloud.microsoft/l/channel/19%3A7fe68fb7bd5c4177ad763516a9fce2e5%40thread.skype/Field%20Notes?groupId=d3d37d91-4c57-4f1b-b0ae-a4489fed1673&tenantId=22177130-642f-41d9-9211-74237ad5687d" target="_blank" rel="noreferrer">Open team Field Notes</a><h3>Ticket Tracker · Flyspray</h3><p>Activation required · ticket sync not connected</p><a class="linkbutton" href="https://mawn.geo.msu.edu/flyspray/" target="_blank" rel="noreferrer">Open Ticket Tracker</a><h3>Campbell Scientific</h3><p>Logger file imports supported · live logger access not connected</p><a class="linkbutton" href="https://www.campbellsci.com/customer-center" target="_blank" rel="noreferrer">Open Campbell account</a><h3>Internal Enviroweather API & LoggerNet</h3><p>Not connected</p></div></section><section class="panel"><div class="panelhead"><div><h2>Observation freshness</h2><p>Overview and daily review</p></div></div><div class="panelbody"><form id="thresholdForm" class="formgrid"><div class="field"><label for="threshold-delayed">Delayed after (minutes)</label><input id="threshold-delayed" name="delayed" type="number" min="5" value="${state.connection.delayed||60}" required></div><div class="field"><label for="threshold-stale">Stale after (minutes)</label><input id="threshold-stale" name="stale" type="number" min="6" max="10080" value="${state.connection.stale||180}" required></div><button class="primary">Save thresholds</button></form></div></section><section class="panel"><div class="panelhead"><div><h2>Workspace export</h2><p>Readings, cases, tests and completed visits</p></div></div><div class="panelbody"><a class="linkbutton" href="/api/export">${icon('download')} Download workspace JSON</a></div></section>`;}
function accountPage(){return heading('Account','My account',`${esc(state.user.name||'')}${state.user.name?' · ':''}${esc(state.user.email)}${state.user.role?' · '+esc(state.user.role):''}`)+`<section class="panel"><div class="panelhead"><div><h2>Change password</h2><p>At least 14 characters. Changing your password signs out all devices.</p></div></div><form id="password-form" class="panelbody"><div class="formgrid"><div class="field"><label for="current-password">Current password</label><input id="current-password" name="currentPassword" type="password" required maxlength="256" autocomplete="current-password"></div><div class="field"><label for="new-password">New password</label><input id="new-password" name="password" type="password" required minlength="14" maxlength="256" autocomplete="new-password"></div></div><button type="submit" class="primary">Change password</button></form></section>`;}
function teamPage(){queueMicrotask(loadTeam);return heading('Account','Team access','')+`<section class="panel"><div class="panelhead"><div><h2>Create an invitation</h2><p>Links last seven days and work only for the named email</p></div></div><div class="panelbody"><form id="invite-form" class="formgrid"><div class="field"><label for="invite-email">Teammate email</label><input id="invite-email" type="email" name="email" required></div><div class="field"><label for="invite-role">Access</label><select id="invite-role" name="role"><option value="editor">Editor · investigations and visits</option><option value="viewer">Viewer · read and export</option></select></div><button class="primary" type="submit">Create invitation link</button></form><p id="invite-result" role="status"></p><p class="footnote"></p></div></section><section class="panel"><div class="panelhead"><h2>Members</h2></div><div id="team-members" class="panelbody">Loading team…</div></section>`;}
async function loadTeam(){try{const r=await api('team');teamUsers=r.users;if(view!=='team')return;$('#team-members').innerHTML=teamUsers.map(u=>`<div class="member-row"><div><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${esc(u.role)} · ${u.active?'Active':'Disabled'}</small></div>${u.role!=='owner'?`<button class="small" data-member="${u.id}" data-active="${u.active}">${u.active?'Disable access':'Restore access'}</button>`:''}</div>`).join('');root.querySelectorAll('[data-member]').forEach(b=>b.onclick=async()=>{try{await api('team/users/'+b.dataset.member,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='1'})});await loadTeam();}catch(e){toast(e.message);}});}catch(e){if($('#team-members'))$('#team-members').textContent=e.message;}}
function visitsPage(){queueMicrotask(loadVisits);return heading('Records','Field Notes','',`<a class="linkbutton primary" href="/field-notes/">Open field notebook</a>`)+`<section class="panel"><div class="panelhead"><div><h2>Completed visits</h2></div></div><div id="shared-visits" class="panelbody">Loading visits…</div></section>${help('Visit storage','Publish completed visits from the notebook. Photos stay on the device; share PDFs through Teams.')}`;}
async function loadVisits(){try{sharedVisits=await api('visits');if(view!=='visits')return;$('#shared-visits').innerHTML=sharedVisits.length?sharedVisits.map(v=>`<button class="shared-visit" data-visit="${esc(v.id)}"><span><strong>${esc(v.fields?.siteName||'Station visit')}</strong><small>${esc(v.fields?.date||'Undated')} · ${esc(v.fields?.technicians||v.sharedBy||'')}</small></span><span class="pill connected">Completed</span></button>`).join(''):empty('No published visits yet','Complete a visit in the field notebook and publish it to the team.');root.querySelectorAll('[data-visit]').forEach(b=>b.onclick=()=>showVisit(b.dataset.visit));}catch(e){if($('#shared-visits'))$('#shared-visits').textContent=e.message;}}
async function showVisit(id){try{const v=await api('visits/'+id),d=$('#recordDialog');d.innerHTML=`<h2>${esc(v.fields.siteName)} · ${esc(v.fields.date)}</h2><p class="footnote">Published by ${esc(v.sharedBy)} · ${date(v.sharedAt)} ET</p><dl class="visit-details">${Object.entries(v.fields).filter(([k,val])=>val!==''&&val!==null&&val!==false).map(([k,val])=>`<dt>${esc(name(k.replace(/([A-Z])/g,'_$1').toLowerCase()))}</dt><dd>${esc(typeof val==='object'?JSON.stringify(val):val===true?'Yes':val)}</dd>`).join('')}</dl><p class="footnote">${esc(v.attachmentNote||'Photos remain in the local notebook.')}</p><div class="actions"><a class="linkbutton" href="/field-notes/?visit=${encodeURIComponent(v.id)}">Open shared copy in notebook</a><button id="download-visit">Download visit</button><button class="primary" id="close-visit">Close</button></div>`;d.showModal();$('#download-visit').onclick=()=>download(v,'field-visit-'+v.id+'.json');$('#close-visit').onclick=()=>d.close();}catch(e){toast(e.message);}}
function bind(){bindReportTools({view,api,rerender:render,state,openStation,setView,currentView:()=>view});const ctx={state,api,toast,rerender:render,setView,openStation,openIncident,openPlan,openPacket,openPlanner,reload:load,download,downloadFromAPI,view};bindOps(ctx);bindPlanner(ctx);bindFleetSettings(ctx);if($('#product-download')&&productCache)$('#product-download').onclick=()=>download(productCache.data,productCache.station+'-'+productCache.service+'-'+productCache.hours+'h.json');if($('#password-form'))$('#password-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await post('auth/password',Object.fromEntries(new FormData(e.target)));setSession('');showAuth(root,()=>load());toast('Password changed. Sign in with your new password.');}catch(error){toast(error.message);}finally{b.disabled=false;}};root.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>loadProduct(b.dataset.product,b));if($('#signout'))$('#signout').onclick=()=>signOut();if($('#thresholdForm'))$('#thresholdForm').onsubmit=async e=>{e.preventDefault();try{await post('thresholds',{delayed:Number(e.target.delayed.value),stale:Number(e.target.stale.value)});await load();toast('Thresholds saved.');}catch(error){toast(error.message);}};if($('#invite-form'))$('#invite-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await post('team/invites',Object.fromEntries(new FormData(e.target)));$('#invite-result').innerHTML=`<label for="invite-link">Invitation for ${esc(r.email)}</label><input id="invite-link" readonly value="${esc(r.url)}"><button id="copy-invite" type="button" class="small">Copy link</button>`;$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(r.url);toast('Invitation copied.');}catch{$('#invite-link').select();toast('Select and copy the invitation link.');}};}catch(err){toast(err.message);}finally{b.disabled=false;}};root.querySelectorAll('[data-investigate]').forEach(b=>b.onclick=()=>startInvestigation(b.dataset.investigate));root.querySelectorAll('[data-review-filter]').forEach(b=>b.onclick=()=>{reviewFilter=b.dataset.reviewFilter;render();});root.querySelectorAll('[data-case-filter]').forEach(b=>b.onclick=()=>{caseFilter=b.dataset.caseFilter;render();});if($('#compare-load'))$('#compare-load').onclick=loadComparison;if($('#compare-variable'))$('#compare-variable').onchange=e=>{comparisonVariable=e.target.value;render();};root.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>setView(b.dataset.nav));root.querySelectorAll('[data-refresh]').forEach(b=>b.onclick=refresh);bindStationLinks();root.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>newRecord(b.dataset.new,b.dataset.prefill));root.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>showRecord(b.dataset.record));if($('#search'))$('#search').oninput=e=>{search=e.target.value;updateTable();};if($('#filter'))$('#filter').onchange=e=>{filter=e.target.value;updateTable();};if($('#history-hours'))$('#history-hours').onchange=e=>{historyHours=Number(e.target.value);productCache=null;comparisonTicket++;comparison=null;comparisonBusy=false;history=null;historyError='';fetchHistory();};if($('#history-variable'))$('#history-variable').onchange=e=>{historyVariable=e.target.value;render();};if($('[data-retry-history]'))$('[data-retry-history]').onclick=()=>{historyError='';fetchHistory();};if($('#download-history'))$('#download-history').onclick=()=>download(history,'station-'+selected+'-'+historyHours+'h.json');if($('#connect-form'))$('#connect-form').onsubmit=connect;if($('#threshold-form'))$('#threshold-form').onsubmit=async e=>{e.preventDefault();try{await post('thresholds',{delayed:Number($('#delayed').value),stale:Number($('#stale').value)});await load();toast('Triage thresholds saved.');}catch(e){toast(e.message);}};if($('#csv-file'))$('#csv-file').onchange=analyzeFile;if($('#file-variable'))$('#file-variable').onchange=e=>{analysisVariable=e.target.value;render();};if($('#download-analysis'))$('#download-analysis').onclick=()=>download(analysis,'logger-analysis.json');}
function bindStationLinks(){root.querySelectorAll('[data-station]').forEach(b=>b.onclick=()=>openStation(b.dataset.station));}
function openStation(id,{push=true,draw=true}={}){productCache=null;comparisonTicket++;comparison=null;comparisonBusy=false;selected=id;history=null;historyError='';historyLoading=false;historyTicket++;refreshStation();view='station';if(push)pushHash();if(draw)render();}
function updateTable(){$('#stationrows').innerHTML=stationRows(filtered());$('#resultcount').textContent=filtered().length+' stations';$('#noresults').hidden=filtered().length>0;bindStationLinks();}
async function refresh(){if(!state.connection.configured){setView('connections');return;}busy=true;render();try{await post('refresh');refreshStation();refreshIncident();await load();toast('Network snapshot updated.');}catch(e){toast(e.message);await load();}finally{busy=false;render();}}
async function connect(e){e.preventDefault();const b=e.target.querySelector('button'),token=$('#token').value;b.disabled=true;$('#connect-message').textContent='Checking your token and identifying the network…';try{const r=await post('connect',{token});$('#token').value='';if(!r.network){$('#connect-message').innerHTML=`<p>Choose your network:</p><select id="network-choice">${r.candidates.map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('')}</select><button id="choose-network">Use this network</button>`;$('#choose-network').onclick=async()=>{try{await post('network',{network:$('#network-choice').value});await load();await refresh();}catch(e){toast(e.message);}};return;}await load();await refresh();toast('Synoptic connected.');}catch(e){$('#connect-message').textContent=e.message;}finally{b.disabled=false;}}
function drawMap(){if(!window.L||!$('#map'))return;map=L.map('map',{scrollWheelZoom:false,zoomAnimation:false,fadeAnimation:false,zoomSnap:.25,attributionControl:true}).setView([44.4,-85.7],6);const thisMap=map;map.createPane('geography').style.zIndex=200;map.attributionControl.addAttribution('<a href="https://www.naturalearthdata.com">Natural Earth</a>');geographyPromise ||= Promise.all([fetch('/region.geojson').then(r=>r.json()),fetch('/lakes.geojson').then(r=>r.json())]);geographyPromise.then(([region,lakes])=>{if(map!==thisMap)return;L.geoJSON(region,{pane:'geography',interactive:false,style:{color:'#c8d1bf',weight:1,fillColor:'#f0f2e6',fillOpacity:1}}).addTo(map);L.geoJSON(lakes,{pane:'geography',interactive:false,style:{color:'#c9d9d3',weight:1,fillColor:'#dce8e4',fillOpacity:1}}).addTo(map);for(const [label,lat,lon] of [['MICHIGAN',43.8,-84.9],['WISCONSIN',44.1,-89.5],['ONTARIO',44.1,-81.7],['Lake Michigan',44.1,-87],['Lake Huron',44.8,-82.5]])L.marker([lat,lon],{interactive:false,icon:L.divIcon({className:'map-label',html:label,iconSize:[110,20]})}).addTo(map);}).catch(()=>toast('Map outlines unavailable; station coordinates remain visible.'));const coords=[],markers=new Map(),tiered=view==='overview'&&state.ops;for(const s of state.stations){if(s.lat===null||s.lon===null)continue;coords.push([s.lat,s.lon]);const st=tiered?markerStyle(s,state.ops):null;const marker=L.circleMarker([s.lat,s.lon],{radius:st?st.radius:s.status==='inactive'?3:5,color:'#fff',weight:1.5,fillColor:st?st.fill:colors[s.status],fillOpacity:s.status==='inactive'?.5:.95}).addTo(map);markers.set(s.id,marker);marker.bindTooltip(`<strong>${esc(s.name)}</strong><br>${esc(s.id)} · ${esc(st?st.label:labels[s.status])}<br>Newest ${esc(ago(s.ageMinutes))}`);marker.on('click',()=>{queueMicrotask(()=>{if(map!==thisMap)return;if(tiered&&selectFromMap(s.id,state.ops))return;openStation(s.id);});});}
 if(tiered)registerMap({focus(ids){const pts=ids.map(id=>markers.get(id)).filter(Boolean);if(!pts.length||map!==thisMap)return;thisMap.fitBounds(L.featureGroup(pts).getBounds(),{padding:[40,40],maxZoom:9});pts.forEach(m=>{m.setStyle({color:'#1b2a25',weight:3});setTimeout(()=>m.setStyle({color:'#fff',weight:1.5}),4000);});pts[0].openTooltip();$('#map')?.scrollIntoView({block:'nearest',behavior:'smooth'});}});map.fitBounds([[41.5,-90.5],[48.3,-82.1]],{padding:[18,18]});if(view==='station'){const focus=state.stations.find(s=>s.id===selected);const points=[focus,...neighbors(focus,state.stations)].filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lon));if(points.length)map.fitBounds(points.map(s=>[s.lat,s.lon]),{padding:[40,40],maxZoom:9});if(focus&&Number.isFinite(focus.lat)&&Number.isFinite(focus.lon))L.circleMarker([focus.lat,focus.lon],{radius:11,color:'#163b31',weight:3,fill:false}).addTo(map);}drawRadar(thisMap);}
function newRecord(kind,station='',existing=null){const d=$('#recordDialog');d.innerHTML=`<form id="record-form"><h2>${kind==='bench'?'New bench test':existing?.caseType==='investigation'?'Edit investigation':'New field note'}</h2><div class="formgrid"><div class="field wide"><label for="rtitle">Title</label><input id="rtitle" name="title" required maxlength="200" placeholder="${kind==='bench'?'e.g. Soil temperature sensor comparison':'e.g. Investigate missing wind observations'}"></div><div class="field wide"><label for="rstation">Station name or ID</label><input id="rstation" name="station" list="station-options" value="${esc(station)}" ${existing?.caseType==='investigation'?'readonly':''}><datalist id="station-options">${state.stations.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('')}</datalist></div>${kind==='bench'?`<div class="field"><label for="requipment">Logger / sensor / serial</label><input id="requipment" name="equipment"></div><div class="field"><label for="rprogram">Program name / version</label><input id="rprogram" name="program"></div><div class="field wide"><label for="rexpected">Procedure and expected result</label><textarea id="rexpected" name="expected" required></textarea></div><div class="field wide"><label for="robserved">Observed result / evidence</label><textarea id="robserved" name="observed" required></textarea></div><div class="field"><label for="routcome">Conclusion</label><select id="routcome" name="outcome"><option value="inconclusive">Inconclusive</option><option value="pass">Pass</option><option value="fail">Fail</option></select></div>`:''}<div class="field wide"><label for="rnotes">${kind==='bench'?'Notes and next steps':'Evidence, suspected cause, and next check'}</label><textarea id="rnotes" name="notes" ${kind==='issue'?'required':''}></textarea></div></div>${existing?.caseType==='investigation'?'<div class="field"><label for="rplanned">Planned field checks</label><textarea id="rplanned" name="plannedChecks" maxlength="5000"></textarea></div>':''}<div class="actions"><button type="button" id="cancel-record">Cancel</button><button class="primary" type="submit">Save record</button></div></form>`;d.showModal();if(existing){for(const [key,value] of Object.entries(existing)){const field=$('#record-form').elements.namedItem(key);if(field)field.value=value??'';}d.querySelector('h2').textContent='Edit '+(kind==='bench'?'bench test':existing.caseType==='investigation'?'investigation':'field note');}$('#cancel-record').onclick=()=>d.close();$('#record-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{const payload={...Object.fromEntries(new FormData(e.target)),kind,...(existing?{revision:existing._revision}:{})};if(existing)await api('records/'+existing.id,{method:'PATCH',body:JSON.stringify(payload)});else await post('records',payload);d.close();await load();toast('Record saved.');}catch(e){toast(e.message);}finally{b.disabled=false;}};}
async function showRecord(id,snapshotIndex){let r;try{r=await api('records/'+id);const i=state.records.findIndex(x=>x.id===id);if(i>=0)state.records[i]=r;}catch(error){toast(error.message);return;}const d=$('#recordDialog');d.innerHTML=`<h2>${esc(r.title)}</h2><p>${pill(r.status)} <span class="mono">${esc(r.station)}</span></p><p class="footnote">Created ${date(r.created)} ET · ${esc(r.source)}</p>${r.kind==='bench'?`<h3>Equipment / program</h3><p>${esc(r.equipment)} · ${esc(r.program)}</p><h3>Procedure / expected</h3><p class="report">${esc(r.expected)}</p><h3>Observed</h3><p class="report">${esc(r.observed)}</p><p>Conclusion: ${pill(r.outcome)}</p>`:''}<h3>Notes</h3><p class="report">${esc(r.notes)}</p>${r.caseType==='investigation'?`<h3>Planned field checks</h3><p class="report">${esc(r.plannedChecks||'Not recorded yet.')}</p>${evidenceSummary(r,snapshotIndex)}<div class="handoff-actions"><a class="linkbutton primary" href="/field-notes/?case=${encodeURIComponent(r.id)}">Prepare field visit</a><button id="capture-evidence" class="small">Save current evidence</button><a class="linkbutton" href="/api/records/${r.id}/handoff?format=text">${icon('download')} Visit handoff · text</a><a class="linkbutton" href="/api/records/${r.id}/handoff">${icon('download')} Handoff + evidence · JSON</a></div>`:''}${r.activity?.length?`<details><summary>Case activity · ${r.activity.length} events</summary><ul>${r.activity.map(a=>`<li>${date(a.at)} ET · ${esc(a.action)}</li>`).join('')}</ul></details>`:''}<div class="actions"><button id="edit-record">Edit</button><button id="export-record">Download record</button><button id="resolve-record">${r.status==='open'?'Mark resolved':'Reopen'}</button><button class="primary" id="close-record">Close</button></div>`;d.showModal();if($('#snapshot-select'))$('#snapshot-select').onchange=e=>showRecord(r.id,Number(e.target.value));if($('#capture-evidence'))$('#capture-evidence').onclick=()=>appendEvidence(r);$('#close-record').onclick=()=>d.close();$('#edit-record').onclick=()=>{d.close();newRecord(r.kind,r.station,r);};$('#export-record').onclick=()=>download(r,'diagnostic-record-'+r.id+'.json');$('#resolve-record').onclick=async()=>{try{await api('records/'+r.id,{method:'PATCH',body:JSON.stringify({status:r.status==='open'?'resolved':'open',revision:r._revision})});d.close();await load();toast('Record updated.');}catch(e){toast(e.message);}};}
async function analyzeFile(e){const version=sessionGeneration(),file=e.target.files[0];if(!file)return;if(file.size>8*1024*1024){toast('Choose a file smaller than 8 MB.');return;}try{const text=await file.text();if(version!==sessionGeneration()||!hasSession())return;const result=analyzeCSV(text);analysis=result;analysisName=file.name;render();toast('File analyzed locally.');}catch(e){toast(e.message);}}
function download(data,filename){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
if(hasSession())load();else showAuth(root,()=>load());

function drawRadar(thisMap){
  thisMap.createPane('radar').style.zIndex=300;
  thisMap.getPane('radar').style.pointerEvents='none';
  let layer=null, errors=false, loadingTimeout;
  const status=text=>{if(map===thisMap&&$('#radar-status'))$('#radar-status').textContent=text;};
  function refreshRadar(){
    if(map!==thisMap)return;
    clearTimeout(loadingTimeout);
    if(layer){layer.off();thisMap.removeLayer(layer);layer=null;}
    if(!radarEnabled){status('Radar hidden · station footprint remains visible');return;}
    errors=false;status('Loading latest radar…');
    layer=L.tileLayer.wms('https://mesonet.agron.iastate.edu/cgi-bin/wms/nexrad/n0q.cgi',{
      layers:'nexrad-n0q',format:'image/png',transparent:true,version:'1.1.1',
      pane:'radar',opacity:radarOpacity,updateWhenIdle:true,keepBuffer:0,
      bounds:[[40,-93],[50,-79]],attribution:'Radar: NWS / Iowa Environmental Mesonet',
      refresh:Math.floor(Date.now()/300000)
    });
    layer.on('loading',()=>{errors=false;status('Loading latest radar…');});
    layer.on('tileerror',()=>{errors=true;status('Radar incomplete or unavailable · do not interpret blank areas as clear weather');});
    layer.on('load',()=>{clearTimeout(loadingTimeout);if(!errors)status('Radar imagery loaded '+date(new Date().toISOString())+' ET · latest available mosaic');});
    layer.addTo(thisMap);
    loadingTimeout=setTimeout(()=>{if(map===thisMap&&layer?.isLoading())status('Radar is slow to respond · imagery may be incomplete');},20000);
  }
  $('#radar-toggle').onchange=e=>{radarEnabled=e.target.checked;refreshRadar();};
  $('#radar-opacity').oninput=e=>{radarOpacity=Number(e.target.value)/100;layer?.setOpacity(radarOpacity);};
  $('#radar-refresh').onclick=refreshRadar;
  thisMap.on('unload',()=>{clearTimeout(loadingTimeout);layer?.off();});
  refreshRadar();radarTimer=setInterval(refreshRadar,300000);
}

function comparisonPanel(s){
 const nearby=neighbors(s,state.stations);
 return `<section class="panel"><div class="panelhead"><div><h2>Compare neighbors</h2><p>Up to five active stations within 100 km · ${historyHours} hours</p></div><button id="compare-load" class="primary" ${comparisonBusy?'disabled':''}>${comparisonBusy?'Loading neighbors…':comparison?'Refresh comparison':'Compare nearby stations'}</button></div><div class="panelbody">${comparison?comparisonContent(s):`<p>${nearby.length?nearby.map(n=>esc(n.name)+' ('+num(n.distance)+' km)').join(' · '):'No active neighbors with valid coordinates within 100 km.'}</p>`}${help('Comparison details','QC-flagged readings are excluded from the median. Station exposure and local weather can differ.')}</div></section>`;
}
async function loadComparison(){
 const ticket=++comparisonTicket,id=selected,s=state.stations.find(s=>s.id===id),nearby=neighbors(s,state.stations);comparisonBusy=true;render();
 const results=[];for(const station of [s,...nearby]){if(ticket!==comparisonTicket)return;try{const data=await api('history?station='+encodeURIComponent(station.id)+'&hours='+historyHours);results.push({station,data});}catch(e){results.push({station,error:e.message});}}
 if(ticket!==comparisonTicket||selected!==id)return;comparison=results;comparisonBusy=false;render();
}
function comparisonContent(s){
 const palette=['#163b31','#ba582e','#5267b1','#a03b82','#208d99','#8a741f'];
 const rows=comparison.map((r,i)=>({...r,...series(r.data,comparisonVariable),color:palette[i]}));
 const target=rows[0],usable=rows.filter(r=>r.unit===target.unit),ref=reference(target,usable.slice(1));
 return `<div class="filters"><label for="compare-variable">Compare</label><select id="compare-variable">${[['air_temp','Air temperature'],['relative_humidity','Relative humidity'],['wind_speed','Wind speed'],['solar_radiation','Solar radiation'],['precip_accum_one_hour','Rainfall — preceding hour']].map(([v,n])=>`<option value="${v}" ${v===comparisonVariable?'selected':''}>${n}</option>`).join('')}</select><span>${unitLabel(target.unit)||'Units unavailable'}</span></div>${comparisonChart(usable)}<p class="info">${ref?`At ${date(ref.time)} ET: ${esc(s.name)} ${num(ref.value)} ${unitLabel(target.unit)} · neighbor median ${num(ref.median)} · difference ${ref.delta>=0?'+':''}${num(ref.delta)} (${ref.count} neighbors within ±5 minutes).`:'Reference median unavailable: need a target reading without a QC flag and at least two neighbors with matching units within ±5 minutes.'}</p><div class="tablewrap"><table><thead><tr><th>Station / distance</th><th>Series</th><th>Latest in window</th><th>Source / coverage</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong><i class="swatch" style="background:${r.color}"></i>${esc(r.station.name)}</strong><small>${r.station.id===s.id?'Selected station':num(r.station.distance)+' km away'}</small></td><td>${esc(r.key||'Not available')}<small>${r.points.filter(p=>p.flagged).length} QC-flagged readings</small></td><td>${r.points.length?`<strong class="num">${num(r.points.at(-1).v)} <span class="unit">${unitLabel(r.unit)}</span></strong>`:'—'}<small>${date(r.points.at(-1)?.t)} ET</small></td><td>${r.error?esc(r.error):r.points.length+' readings'}<small>${r.data?'Fetched '+date(r.data.fetchedAt)+' ET':''}${r.unit&&r.unit!==target.unit?' · unit mismatch ('+esc(r.unit)+'): excluded from chart and reference':''}</small></td></tr>`).join('')}</tbody></table></div>${help('Chart details','Lines break at gaps over 15 minutes; dots mark QC flags. Uses the first reported sensor for each variable. Rainfall shows preceding-hour totals.')}<h3>Current radar around these stations</h3><p class="footnote">Live radar · selected station outlined</p><div class="radar-controls"><label><input id="radar-toggle" type="checkbox" ${radarEnabled?'checked':''}> Show radar</label><label>Opacity <input id="radar-opacity" type="range" min="10" max="100" value="${radarOpacity*100}"></label><button id="radar-refresh" class="small">Refresh radar</button></div><div id="map" class="map"></div><p id="radar-status" role="status"></p>`;
}
function comparisonChart(rows){
 const points=rows.flatMap(r=>r.points);if(!points.length)return empty('No comparable observations','Try another variable or inspect source errors below.');
 const first=Math.min(...points.map(p=>p.t)),last=Math.max(...points.map(p=>p.t)),lo=Math.min(...points.map(p=>p.v)),hi=Math.max(...points.map(p=>p.v)),span=hi-lo||1;
 const x=t=>50+700*(t-first)/(last-first||1),y=v=>220-180*(v-lo+span*.1)/(span*1.2);
 return `<svg class="chart" viewBox="0 0 780 270" role="img" aria-label="Neighbor comparison with shared time and value axes">${[lo,(lo+hi)/2,hi].map(v=>`<line class="grid" x1="50" x2="750" y1="${y(v)}" y2="${y(v)}"/><text x="45" y="${y(v)}" text-anchor="end">${num(v)}</text>`).join('')}${rows.map(r=>{let prev;const d=r.points.map(p=>{const command=prev&&p.t>prev.t&&p.t-prev.t<=900000?'L':'M';prev=p;return command+x(p.t)+' '+y(p.v);}).join(' ');return `<path d="${d}" fill="none" stroke="${r.color}" stroke-width="${r===rows[0]?3:1.5}"/>${r.points.map(p=>`<circle cx="${x(p.t)}" cy="${y(p.v)}" r="${p.flagged?3:1.8}" fill="${r.color}"><title>${esc(r.station.name)} · ${date(p.t)} ET · ${num(p.v)}${p.flagged?' · QC flagged':''}</title></circle>`).join('')}`;}).join('')}<text x="50" y="253">${date(first)} ET</text><text x="750" y="253" text-anchor="end">${date(last)} ET</text></svg>`;
}

function investigationFor(id){return state.records.find(r=>r.caseType==='investigation'&&r.station===id&&r.status==='open');}
function startInvestigation(id){
 const existing=investigationFor(id);if(existing){showRecord(existing.id);return;}
 const s=state.stations.find(s=>s.id===id);if(!s)return;
 const hours=selected===id?historyHours:24,variable=selected===id?(comparison?comparisonVariable:historyVariable.replace(/_set_\d+.*/,'')||'air_temp'):'air_temp';
 const comparisonIds=selected===id&&comparison?comparison.filter(r=>r.station.id!==id&&r.data).map(r=>r.station.id):[];
 const d=$('#recordDialog');
 d.innerHTML=`<form id="investigation-form"><h2>New investigation · ${esc(s.name)}</h2><div class="info">${esc(compactReason(s))}</div><div class="field"><label for="case-title">Case title</label><input id="case-title" name="title" maxlength="200" required value="${esc(s.name+' — '+(attention(s)?labels[s.status].toLowerCase()+' review':'station review'))}"></div><div class="field"><label for="case-notes">Observations</label><textarea id="case-notes" name="notes" required maxlength="10000" placeholder="What did you observe?"></textarea></div><div class="field"><label for="case-checks">Planned field checks</label><textarea id="case-checks" name="plannedChecks" maxlength="5000" placeholder="Checks to perform on site"></textarea></div><details><summary>Saved readings</summary><p class="footnote">Snapshot ${date(state.fetchedAt)} ET · latest readings and QC · loaded ${hours}-hour ${esc(name(variable))} history · ${comparisonIds.length} loaded neighbors. Saving uses these cached readings.</p><p class="footnote">Load a station comparison first to include neighbor history.</p></details><div class="actions"><button type="button" id="cancel-investigation">Cancel</button><button class="primary" type="submit">Save investigation</button></div></form>`;
 d.showModal();$('#cancel-investigation').onclick=()=>d.close();
 $('#investigation-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const r=await post('investigations',{...Object.fromEntries(new FormData(e.target)),station:id,hours,variable,comparisonIds});d.close();await load();showRecord(r.id);toast(r.existing?'An open case already exists for this station.':'Investigation and fixed evidence snapshot saved.');}catch(err){toast(err.message);}finally{button.disabled=false;}};
}
function evidenceSummary(record,snapshotIndex){
 const chosen=Number.isInteger(snapshotIndex)&&snapshotIndex>=0&&snapshotIndex<record.evidence.length?snapshotIndex:record.evidence.length-1;
 const e=record.evidence?.[chosen];if(!e)return '';
 const ref=e.comparison.reference;
 return `<section class="saved-evidence"><h3>Saved evidence · ${record.evidence.length} snapshot${record.evidence.length===1?'':'s'}</h3>${record.evidence.length>1?`<label for="snapshot-select" class="sr-only">Saved snapshot</label><select id="snapshot-select">${record.evidence.map((snapshot,i)=>`<option value="${i}" ${i===chosen?'selected':''}>Snapshot ${i+1} · ${date(snapshot.capturedAt)} ET</option>`).join('')}</select>`:''}<p class="footnote">Captured ${date(e.capturedAt)} ET · network fetched ${date(e.networkFetchedAt)} ET<br>Requested ${e.window.requestedHours}-hour ${esc(name(e.window.variable))} window · ${e.station.fields.length} latest sensor fields</p><p>${esc(e.reasons.join(' '))}</p><p class="footnote">${e.histories.map(h=>`${esc(h.stationName)}: ${h.available?`${h.points.length} numeric readings (${esc(h.unit||'units unavailable')}); fetched ${date(h.fetchedAt)} ET; ${date(h.windowStart)}–${date(h.windowEnd)} ET`:'history not loaded'}`).join('<br>')}</p><p class="footnote">${ref?`Target ${num(ref.value)} ${esc(ref.unit)} · neighbor median ${num(ref.median)} · difference ${num(ref.delta)} · ${ref.count} neighbors at ${date(ref.time)} ET`:'Neighbor reference unavailable.'}</p><details><summary>Captured latest readings & QC</summary><div class="tablewrap"><table><thead><tr><th>Sensor</th><th>Value</th><th>Source time / QC</th></tr></thead><tbody>${e.station.fields.map(f=>`<tr><td>${esc(f.key)}</td><td>${reading(f.value)} ${esc(f.unit)}</td><td>${date(f.time)} ET<small>${f.qc?.length?esc(f.qc.map(q=>e.qcSummary?.QC_NAMES?.[q]||'Flag '+q).join('; ')):esc(f.qcStatus||'No flag returned')}</small></td></tr>`).join('')}</tbody></table></div></details><p class="footnote">This evidence stays fixed when observations refresh. Complete source timestamps, QC arrays, units, and numeric comparison points are included in the JSON export.</p></section>`;
}
async function appendEvidence(record){
 const d=$('#recordDialog'),onStation=view==='station'&&selected===record.station;
 const hours=onStation?historyHours:24,variable=onStation?(comparison?comparisonVariable:historyVariable.replace(/_set_\d+.*/,'')||'air_temp'):'air_temp';
 const comparisonIds=onStation&&comparison?comparison.filter(r=>r.station.id!==record.station&&r.data).map(r=>r.station.id):[];
 d.innerHTML=`<h2>Save another evidence snapshot</h2><p>This adds current cached readings to <strong>${esc(record.title)}</strong>. All earlier snapshots remain in the case export.</p><p class="footnote">Network fetched ${date(state.fetchedAt)} ET · ${hours}-hour ${esc(name(variable))} history, if cached · ${comparisonIds.length} loaded neighbors. This action does not refresh any observations.</p><p class="footnote">To include a fresh neighbor comparison, return to the station and load the comparison before saving.</p><div class="actions"><button id="cancel-capture">Back to case</button><button class="primary" id="confirm-capture">Save snapshot</button></div>`;
 $('#cancel-capture').onclick=()=>showRecord(record.id);
 $('#confirm-capture').onclick=async()=>{const b=$('#confirm-capture');b.disabled=true;try{await post('records/'+record.id+'/evidence',{hours,variable,comparisonIds});d.close();await load();showRecord(record.id);toast('Another fixed evidence snapshot saved.');}catch(e){toast(e.message);b.disabled=false;}};
}

function bindDownloads(container){container.querySelectorAll('a[href^="/api/"]').forEach(a=>{a.onclick=async e=>{e.preventDefault();try{const path=a.getAttribute('href').slice(5);await downloadFromAPI(path,path.includes('format=text')?'field-handoff.txt':path.includes('handoff')?'field-handoff.json':path==='ops/export'?'enviroweather-operations.json':'enviroweather-workspace.json');}catch(err){toast(err.message);}};});}
new MutationObserver(()=>bindDownloads(document.body)).observe(document.body,{childList:true,subtree:true});
window.addEventListener('fleet-auth-required',()=>{const d=$('#authDialog');if(d.open)return;showAuth(d,async()=>{d.close();toast('Signed in. You can retry saving your open form.');});d.showModal();});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

async function loadProduct(service,button){const id=selected,hours=historyHours;button.disabled=true;try{let data;if(service==='localstats'){if(!history)throw Error('Load observation history first.');const stats={};const raw=history.STATION?.[0];for(const key of Object.keys(raw?.OBSERVATIONS||{})){if(key==='date_time'||!Array.isArray(raw.OBSERVATIONS[key])||key.endsWith('d'))continue;const values=raw.OBSERVATIONS[key].filter((v,i)=>typeof v==='number'&&Number.isFinite(v)&&!(Array.isArray(raw.QC?.[key]?.[i])?raw.QC[key][i].length:raw.QC?.[key]?.[i]));if(!values.length)continue;stats[key]=[{min:Math.min(...values),max:Math.max(...values),mean:values.reduce((a,b)=>a+b,0)/values.length,count:values.length}];}data={STATION:[{STATISTICS:stats}],UNITS:history.UNITS,fetchedAt:history.fetchedAt,cached:true,computedLocally:true};}else data=await api('products?station='+encodeURIComponent(id)+'&hours='+hours+'&service='+service);if(view!=='station'||selected!==id)return;const title={precip:'Rainfall totals',statistics:'Daily statistics',localstats:'Window statistics',qcsegments:'QC history'}[service];$('#product-results').innerHTML=`<h3>${esc(title)} · ${hours} hours</h3><p class="footnote">Fetched ${date(data.fetchedAt)} ET · ${data.computedLocally?'Calculated from loaded history; QC-flagged readings excluded':data.cached?'Saved response':'Synoptic API'}. No returned data means unavailable, rather than zero.</p><div id="product-summary"></div><button id="product-download" class="small">Download source data</button><details><summary>Source response</summary><pre class="source-json">${esc(JSON.stringify(data,null,2))}</pre></details>`;const station=data.STATION?.[0];let rows=[];if(service==='qcsegments')rows=(station?.QC||[]).map(q=>[q.sensor,data.QC_NAMES?.[q.qc_flag]||('Flag '+q.qc_flag),date(q.start),date(q.end),q.is_open?'Open':'Closed']);else if(service==='statistics'||service==='localstats')for(const [sensor,values]of Object.entries(station?.STATISTICS||{}))for(const value of Array.isArray(values)?values:[values])rows.push([sensor+' ('+(data.UNITS?.[sensor.replace(/_set_\d+.*/,'')]||'Units unavailable')+')',value.time_period?.value||'',num(value.min),num(value.max),num(value.mean),value.count??'—']);else{const values=station?.OBSERVATIONS?.precipitation||station?.PRECIPITATION||[];for(const value of Array.isArray(values)?values:[values])rows.push([value.first_report||value.first_report_datetime||value.start||'',value.last_report||value.last_report_datetime||value.end||'',value.total??value.total_precip_value??'—',data.UNITS?.precipitation||data.UNITS?.precip||'Units unavailable']);}$('#product-summary').innerHTML=rows.length?`<div class="tablewrap"><table><thead><tr>${(service==='qcsegments'?['Sensor','QC check','Start · ET','End · ET','Status']:service==='precip'?['First report · UTC','Last report · UTC','Total','Units']:['Sensor','Day · UTC','Minimum','Maximum','Mean','Samples']).map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')}</tbody></table></div>`:'<p>No product values were returned for this station and window. The source response is available below.</p>';productCache={station:id,hours,html:$('#product-results').innerHTML,data,service};$('#product-download').onclick=()=>download(data,id+'-'+service+'-'+hours+'h.json');}catch(error){if($('#product-results'))$('#product-results').textContent=error.message;}finally{button.disabled=false;}}
